/// <summary>
/// Purch table COC form
/// </summary>
[ExtensionOf(FormDataSourcestr(PurchTable, PurchTable))]
final class METPurchTableFormPurchTableDS_Extension
{


}

Method.Source:
    /// <summary>
    /// Create COC method 
    /// </summary>
    /// <param name = "append">Boolean value</param>
    void  create(boolean  append)
    {
        #task
        next create(append);

        FormDataSource          PurchTableDataSource = this as FormDataSource;
        FormDataSource          METPurchTableDataSource = PurchTableDataSource.formRun().dataSource(formDataSourceStr(PurchTable,METpurchTable));
        METpurchTable           METpurchTable = MetPurchTableDataSource.cursor();
        
        if(!METpurchTable)
        {
            METpurchTable.data(METpurchTable::findByPurchTable(PurchTableDataSource.cursor().recid));
            METpurchTable.reread();
        }
        this.formRun().task(#taskRefresh);// VM - CB219 - PO Acknowledgement
    }

    /// <summary>
    /// CB501_ISP_Security
    /// When the parameter is set to ‘yes’, the ‘+new’ button on the ‘All Purchase Orders’ screen 
    /// will be enabled for any user that has the ISP XDS security role assigned. When the parameter is set to no, any users with the security role 
    /// will see the button greyed out and they will not be able to create new POs.
    /// </summary>
    public void init()
    {
        next init();
        
        FormDataSource purchTableDataSource = this as FormDataSource;
        purchTableDataSource.allowCreate(METVendParameters::find().allowISPCreatePO());

        QueryBuildDataSource purchTableDS = this.query().dataSourceTable(tableNum(PurchTable));
        
        if (purchTableDS)
        {
            METPOWarehouseRestrictionHelper::addWarehouseRestrictionRange(purchTableDS);
        }
    }

    /// <summary>
    /// update metPurchTable with latest info from db
    /// </summary>
    void  write()
    {
        next write();

        FormDataSource metPurchTable_ds = this.formRun().dataSource(formDataSourceStr(PurchTable, METPurchTable));

        if (metPurchTable_ds && metPurchTable_ds.cursor())
        {
            metPurchTable_ds.write();            
            metPurchTable_ds.research(true);
            metPurchTable_ds.reread();
        }
    }

    /// <summary>
    /// active method
    /// </summary>
    /// <returns>int</returns>
    int active()
    {
        boolean ret;

        element.metEditPurchOrderFormNum();

        ret = next active();

        PurchTable purchTable = this.cursor();
        FormStringControl byWhs = this.formRun().design().controlName(formControlStr(PurchTable, METPurchTable_BYSourceWarehouse));

        byWhs.allowEdit(purchTable.METIntercompanyTransferReplenishment == NoYes::Yes);

        return ret;
    }
